import{_ as l,a0 as r,w as o,s as p,I as s,x as i,a1 as e,A as a,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Arch Linux（UEFI）上安裝 GRUB | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Arch Linux（UEFI）上安裝 GRUB | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Arch Linux（UEFI）上安裝 GRUB | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Arch Linux（UEFI）上安裝 GRUB | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20181013 How to Install GRUB on Arch Linux (UEFI)","title":"如何在 Arch Linux（UEFI）上安裝 GRUB","tag":"201810","desc":""},"relativePath":"201810/20181013 How to Install GRUB on Arch Linux (UEFI).md","filePath":"[post].md"}'),u={name:"201810/20181013 How to Install GRUB on Arch Linux (UEFI).md"};function b(h,t,g,f,k,x){const n=r("Link");return o(),p("div",null,[t[21]||(t[21]=s("h1",{id:"如何在-arch-linux-uefi-上安裝-grub",tabindex:"-1"},[i("如何在 Arch Linux（UEFI）上安裝 GRUB "),s("a",{class:"header-anchor",href:"#如何在-arch-linux-uefi-上安裝-grub","aria-label":"Permalink to “如何在 Arch Linux（UEFI）上安裝 GRUB”"},"​")],-1)),t[22]||(t[22]=s("p",null,[s("img",{src:"http://fasterland.net/wp-content/uploads/2018/10/Arch-Linux-Boot-Menu-750x375.jpg",alt:""})],-1)),s("p",null,[t[1]||(t[1]=i("前段時間，我寫了一篇在安裝 Windows 後在 Arch Linux 上",-1)),e(n,{href:"http://fasterland.net/reinstall-grub-arch-linux.html"},{default:a(()=>[...t[0]||(t[0]=[i("如何重新安裝 Grub",-1)])]),_:1}),t[2]||(t[2]=i("的教程。",-1))]),t[23]||(t[23]=d(`<p>幾周前，我不得不在我的筆記本上從頭開始重新安裝 Arch Linux，同時我發現安裝 Grub 並不像我想的那麼簡單。</p><p>出於這個原因，由於在新安裝 Arch Linux 時在 UEFI bios 中安裝 Grub 並不容易，所以我要寫這篇教程。</p><h3 id="定位-efi-分區" tabindex="-1">定位 EFI 分區 <a class="header-anchor" href="#定位-efi-分區" aria-label="Permalink to “定位 EFI 分區”">​</a></h3><p>在 Arch Linux 上安裝 Grub 的第一件重要事情是定位 EFI 分區。讓我們運行以下命令以找到此分區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># fdisk -l</span></span></code></pre></div><p>我們需要檢查標記為 EFI System 的分區，我這裏是 <code>/dev/sda2</code>。</p><p>之後，我們需要在例如 <code>/boot/efi</code> 上掛載這個分區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mkdir /boot/efi</span></span>
<span class="line"><span># mount /dev/sdb2 /boot/efi</span></span></code></pre></div><p>另一件重要的事情是將此分區添加到 <code>/etc/fstab</code> 中。</p><h4 id="安裝-grub" tabindex="-1">安裝 Grub <a class="header-anchor" href="#安裝-grub" aria-label="Permalink to “安裝 Grub”">​</a></h4><p>現在我們可以在我們的系統中安裝 Grub：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grub-mkconfig -o /boot/grub/grub.cfg</span></span>
<span class="line"><span># grub-install --target=x86_64-efi --efi-directory=/boot/efi --bootloader-id=GRUB</span></span></code></pre></div><h4 id="自動將-windows-添加到-grub-菜單中" tabindex="-1">自動將 Windows 添加到 Grub 菜單中 <a class="header-anchor" href="#自動將-windows-添加到-grub-菜單中" aria-label="Permalink to “自動將 Windows 添加到 Grub 菜單中”">​</a></h4><p>為了自動將 Windows 條目添加到 Grub 菜單，我們需要安裝 os-prober：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pacman -Sy os-prober</span></span></code></pre></div><p>要添加它，讓我們運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># os-prober</span></span>
<span class="line"><span># grub-mkconfig -o /boot/grub/grub.cfg</span></span>
<span class="line"><span># grub-install --target=x86_64-efi --efi-directory=/boot/efi --bootloader-id=GRUB</span></span></code></pre></div>`,17)),s("p",null,[t[4]||(t[4]=i("你可以在",-1)),e(n,{href:"https://wiki.archlinux.org/index.php/GRUB"},{default:a(()=>[...t[3]||(t[3]=[i("這裏",-1)])]),_:1}),t[5]||(t[5]=i("找到更多關於在 Arch Linux 上 Grub 的信息。",-1))]),t[24]||(t[24]=s("hr",null,null,-1)),s("p",null,[t[7]||(t[7]=i("via: ",-1)),e(n,{href:"http://fasterland.net/how-to-install-grub-on-arch-linux-uefi.html"},{default:a(()=>[...t[6]||(t[6]=[i("http://fasterland.net/how-to-install-grub-on-arch-linux-uefi.html",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=i("作者：",-1)),e(n,{href:"http://fasterland.net/"},{default:a(()=>[...t[8]||(t[8]=[i("Francesco Mondello",-1)])]),_:1}),t[13]||(t[13]=i(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[9]||(t[9]=[i("lujun9972",-1)])]),_:1}),t[14]||(t[14]=i(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:a(()=>[...t[10]||(t[10]=[i("geekpi",-1)])]),_:1}),t[15]||(t[15]=i(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:a(()=>[...t[11]||(t[11]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[18]||(t[18]=i("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[16]||(t[16]=[i("LCTT",-1)])]),_:1}),t[19]||(t[19]=i(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:a(()=>[...t[17]||(t[17]=[i("Linux中國",-1)])]),_:1}),t[20]||(t[20]=i(" 榮譽推出",-1))])])}const U=l(u,[["render",b]]);export{C as __pageData,U as default};
